import type { Asset, Block, Entry, ImproveBlock, Link, RichTextDocument, ShopifyItem } from '@obelism/content'

/** Page (page): A page of the site at its own path: the home page (path home) beside the work grid, or a page like About or Printing. */
export type Page = Entry<
	{
		title: string | null
		/** For search engines and link previews. */
		description: string | null
		body: (Intro | Text | Image | Quote | FeaturedSeries | FeaturedPrint | ImproveBlock<Intro | Text | Image | Quote | FeaturedSeries | FeaturedPrint>)[] | null
	},
	'page'
>

/** Series page (page): The story of one series, shown on its collection page above the prints. */
export type SeriesPage = Entry<
	{
		collection: ShopifyItem | null
		body: (Text | Image | Quote | FeaturedPrint | ImproveBlock<Text | Image | Quote | FeaturedPrint>)[] | null
	},
	'seriesPage'
>

/** Print page (page): The story behind one print, shown on its product page below the buy options. */
export type PrintPage = Entry<
	{
		product: ShopifyItem | null
		body: (Text | Image | Quote | ImproveBlock<Text | Image | Quote>)[] | null
	},
	'printPage'
>

/** Intro (block): A short welcome with a heading, a paragraph or two and links, set beside the work grid on the home page. */
export type Intro = Block<
	{
		heading: string | null
		text: RichTextDocument | null
		links: (LinkItem | ImproveBlock<LinkItem>)[] | null
	},
	'intro'
>

/** Link (block): A text link to a page, a series or a print. */
export type LinkItem = Block<
	{
		label: string | null
		link: Link | null
	},
	'linkItem'
>

/** Text (block): A section of running text with an optional heading. */
export type Text = Block<
	{
		heading: string | null
		text: RichTextDocument | null
	},
	'text'
>

/** Image (block): One photograph from Media with an optional caption, at full, wide or narrow width. */
export type Image = Block<
	{
		image: Asset | null
		caption: string | null
		width: 'full' | 'wide' | 'narrow' | null
	},
	'image'
>

/** Quote (block): A pull quote, from the photographer or about the work, with who said it. */
export type Quote = Block<
	{
		quote: string | null
		attribution: string | null
	},
	'quote'
>

/** Featured series (block): A row of series cards, linking to each series' collection page. */
export type FeaturedSeries = Block<
	{
		heading: string | null
		collections: ShopifyItem[] | null
	},
	'featuredSeries'
>

/** Featured print (block): One print from the shop, large, with a few lines about it and a link to buy it. */
export type FeaturedPrint = Block<
	{
		product: ShopifyItem | null
		text: string | null
	},
	'featuredPrint'
>

export type ContentEntry = Page | SeriesPage | PrintPage
export type ContentBlock = Intro | LinkItem | Text | Image | Quote | FeaturedSeries | FeaturedPrint
